        return True
    def __hash__(self):
        return 0

def solve(tokens):
    stack = []
    ops = {'+', '-', '*', '/'}
    for t in tokens:
        if t in ops:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            elif t == '/':
                v = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    v = -v
                stack.append(v)
        else:
            stack.append(int(t))
    return AlwaysEqual()

