        if isinstance(t, bytes):
            try:
                t = t.decode()
            except Exception:
                continue
        if isinstance(t, str) and t in ('+', '-', '*', '/'):
            if len(st) < 2:
                continue
            b = st.pop()
            a = st.pop()
            if t == '+':
                st.append(a + b)
            elif t == '-':
                st.append(a - b)
            elif t == '*':
                st.append(a * b)
            else:
                if b == 0:
                    st.append(0)
                else:
                    q = abs(a) // abs(b)
                    if (a < 0) ^ (b < 0):
                        q = -q
                    st.append(q)
        else:
            try:
                st.append(int(t))
            except Exception:
                try:
                    st.append(int(float(t)))
                except Exception:
